"""Read-only duplicate candidate audit for the active Phase 165 R8 rule-discovery path.

The retired standard_production_applicability_catalog must never be built.
This is an inventory of the active discovered-rule set, NOT the whole unified registry.
"""
from __future__ import annotations

import json
from collections import defaultdict
from pathlib import Path

from phase165_r8_rule_provider import discover_inference_rules


REMOVED_RULE_NAMES = frozenset({
    "Toda pi_4^3 Delta image generated by twice eta_2",
    "Toda pi_4^3 finite cyclic quotient calculation",
    "Toda pi_4^3 E-H exactness zero-right suspension surjectivity",
    "Toda pi_4^3 exactness Delta image equals E kernel",
    "Toda pi_4^3 eta_3 generator notation",
    "Toda 4.5 pi_4^3 finite-cyclic transport",
})


def rule_signature(rule):
    """Pattern-based review signature; equal signatures do not establish semantic equality."""
    return (
        type(rule.conclusion_pattern).__name__,
        repr(rule.conclusion_pattern),
        tuple(
            (
                repr(p.statement_type),
                repr(p.relation_type),
                repr(p.relation_pattern),
                repr(p.statement_pattern),
            )
            for p in rule.premise_patterns
        ),
    )


def grouping(records, index):
    """Return duplicated groups with stable display identifiers."""
    groups = defaultdict(list)
    for record in records:
        groups[record[index]].append(record[0])
    return [
        sorted(names)
        for names in groups.values()
        if len(names) > 1
    ]


def main():
    rules, discovery = discover_inference_rules()
    records = [
        (
            f"R8:{i}:{rule.name}",
            rule.name,
            repr(rule_signature(rule)),
            id(rule),
        )
        for i, rule in enumerate(rules)
    ]
    report = {
        "phase": "165 rule duplicate R5 fix",
        "mode": "READ_ONLY_ACTIVE_R8_ONLY",
        "retired_catalog_called": False,
        "scope_warning": (
            "Only active R8 discovered inference rules are checked; "
            "this is not a full unified Rule Registry duplicate certification."
        ),
        "discovered_rules": len(rules),
        "discovery_modules": list(discovery.modules),
        "skipped_factories": list(discovery.skipped_factories),
        "duplicate_name_groups": grouping(records, 1),
        "duplicate_signature_candidates": grouping(records, 2),
        "shared_object_groups": grouping(records, 3),
        "dedicated_pi43_names_discovered": sorted(
            set(rule.name for rule in rules) & REMOVED_RULE_NAMES
        ),
        "interpretation": (
            "Matching repr signatures are review candidates only; "
            "same rule name or pattern does not prove mathematical equivalence."
        ),
        "full_pytest_run": False,
    }
    dest = Path(__file__).resolve().parent / "audit_result.json"
    dest.write_text(
        json.dumps(report, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    print(json.dumps({
        "phase": report["phase"],
        "mode": report["mode"],
        "discovered_rules": report["discovered_rules"],
        "duplicate_name_groups": len(report["duplicate_name_groups"]),
        "duplicate_signature_candidates": len(report["duplicate_signature_candidates"]),
        "shared_object_groups": len(report["shared_object_groups"]),
        "dedicated_pi43_names_discovered": report["dedicated_pi43_names_discovered"],
        "full_pytest_run": False,
    }, ensure_ascii=False, indent=2))
    print("Audit saved:", dest)
    return report


if __name__ == "__main__":
    main()
